import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type InvestmentGrowthEquationProps = Record<string, any>;

const InvestmentGrowthEquation: React.FC<InvestmentGrowthEquationProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  textColor = "#ffffff",
  accentColor = "#4ade80", // Green for growth
  initialAmountText = "$2,000,000",
  rateText = "8% Returns",
  finalAmountText = "$4,300,000",
  durationInSeconds = 8,
  fontSize = 80,
}) => {
  useFontLoader(["Kalam"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Handling
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Timing Configuration
  const totalFrames = durationInSeconds * fps;
  const fadeOutStart = totalFrames - fps; // Last 1 second for fade out

  // Entrance Timing
  const step1Start = 0; // Show first number
  const step2Start = fps * 0.8; // Draw arrow
  const step3Start = fps * 1.5; // Show result

  // --- Animations ---

  // 1. Initial Amount "Write On" (Clip Path Wipe)
  const reveal1 = interpolate(
    frame,
    [step1Start, step1Start + fps * 0.8],
    [100, 0],
    {
      easing: Easing.out(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 2. Arrow Draw (Stroke Dashoffset)
  const arrowLength = 300; // Estimated length of SVG path
  const arrowDraw = interpolate(
    frame,
    [step2Start, step2Start + fps * 0.8],
    [arrowLength, 0],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const rateOpacity = interpolate(
    frame,
    [step2Start + 10, step2Start + fps * 0.5],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  // 3. Final Amount "Write On"
  const reveal3 = interpolate(
    frame,
    [step3Start, step3Start + fps * 0.8],
    [100, 0],
    {
      easing: Easing.out(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 4. Hover Effect (Continuous Floating)
  // Starts gently after entrance
  const hoverStart = step3Start + fps;
  const hoverOffset = Math.sin((frame - hoverStart) / 20) * 10;
  const activeHover = frame > hoverStart ? hoverOffset : 0;

  // 5. Global Fade Out
  const globalOpacity = interpolate(
    frame,
    [fadeOutStart, totalFrames],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Styling constants
  const fontStyle: React.CSSProperties = {
    fontFamily: "Kalam, cursive",
    fontWeight: 700,
    fontSize: fontSize,
    color: textColor,
    whiteSpace: "nowrap",
  };

  const labelStyle: React.CSSProperties = {
    fontFamily: "Kalam, cursive",
    fontSize: fontSize * 0.4,
    color: accentColor,
    position: "absolute",
    top: -fontSize * 0.5,
    left: "50%",
    transform: "translateX(-50%)",
    whiteSpace: "nowrap",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          opacity: globalOpacity,
          transform: `translateY(${activeHover}px)`,
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            gap: width * 0.05,
          }}
        >
          {/* Part 1: Initial Amount */}
          <div
            style={{
              position: "relative",
              clipPath: `inset(0 ${reveal1}% 0 0)`,
              ...fontStyle,
            }}
          >
            {initialAmountText}
          </div>

          {/* Part 2: Arrow & Rate */}
          <div
            style={{
              position: "relative",
              width: fontSize * 3,
              height: fontSize,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
            }}
          >
            {/* Rate Text above arrow */}
            <div style={{ ...labelStyle, opacity: rateOpacity }}>
              {rateText}
            </div>

            {/* SVG Arrow */}
            <svg
              width="100%"
              height="100%"
              viewBox="0 0 100 30"
              style={{ overflow: "visible" }}
            >
              {/* Main Line */}
              <path
                d="M 5 15 Q 50 5, 90 15"
                fill="none"
                stroke={textColor}
                strokeWidth="4"
                strokeLinecap="round"
                strokeDasharray={arrowLength}
                strokeDashoffset={arrowDraw}
                style={{
                    opacity: frame > step2Start ? 1 : 0
                }}
              />
              {/* Arrow Head */}
              <path
                d="M 85 10 L 95 15 L 85 20"
                fill="none"
                stroke={textColor}
                strokeWidth="4"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray={30}
                strokeDashoffset={arrowDraw > 0 ? 30 : 0} // Quick reveal at end
                style={{
                  transition: "none",
                  opacity: frame > step2Start + fps * 0.5 ? 1 : 0, // Delay head slightly
                }}
              />
            </svg>
          </div>

          {/* Part 3: Final Amount */}
          <div
            style={{
              position: "relative",
              clipPath: `inset(0 ${reveal3}% 0 0)`,
              color: accentColor, // Highlight the result
              ...fontStyle,
            }}
          >
            {finalAmountText}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default InvestmentGrowthEquation;